sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float2 center;
uniform float sampling;
uniform float style;
uniform float4 screen;

float2 band(float2 c, float2 d, float lo, float hi, float slope, int ch) {
    float sum = 0.0;
    float alpha = 0.0;
    float total = 0.0;
    for (int i = 0; i < 24; ++i) {
        float u = (float(i) + 0.5) / 24.0;
        float w = max(1.0 + slope * (u - 0.5), 0.0);
        half4 v = image.eval(clamp(c + d * (1.0 + lo + (hi - lo) * u), screen.xy + 0.5, screen.xy + screen.zw - 0.5));
        sum += (ch == 0 ? float(v.r) : ch == 1 ? float(v.g) : float(v.b)) * w;
        alpha += float(v.a) * w;
        total += w;
    }
    return float2(sum, alpha) / total;
}

half4 main(float2 coord) {
    if (style > 0.5) {
        float2 c = center * size;
        float2 d = coord - c;
        float s = clamp(amount, 0.0, 1.9);
        float2 r = band(c, d, 0.10 * s, 0.42 * s, -1.0, 0);
        float2 g = band(c, d, -0.12 * s, 0.22 * s, 0.0, 1);
        float2 b = band(c, d, -0.46 * s, 0.0, 1.5, 2);
        float a = max(r.y, max(g.y, b.y));
        float k = min(s / 0.1, 1.0);
        return half4(half3(min(float3(r.x * (1.0 - 0.09 * k), g.x, b.x * (1.0 + 0.087 * k)), float3(a))), half(a));
    }

    if (sampling > 0.5) {
        float2 c = center * size;
        float2 d = coord - c;
        float s = clamp(amount, 0.0, 1.9) * 4.54;
        float3 shift = float3(0.38, 0.11, -0.215);
        float3 zoom = exp(s * shift);
        float3 sum = float3(0);
        float coverage = 0.0;
        for (int i = 0; i < 32; ++i) {
            float t = float(i) / 31.0 - 0.5365;
            float3 factor = zoom * (1.0 + s * (float3(t) + shift));
            half4 r = image.eval(c + d * factor.r);
            half4 g = image.eval(c + d * factor.g);
            half4 b = image.eval(c + d * factor.b);
            sum += float3(r.r, g.g, b.b);
            coverage += (float(r.a) + float(g.a) + float(b.a)) / 3.0;
        }
        float a = coverage / 32.0;
        return half4(half3(min(sum / 32.0, float3(a))), half(a));
    }

    float2 c = center * size;
    float2 d = coord - c;
    float s = clamp(amount, 0.0, 1.9);
    float4 sum = float4(0);
    float4 weight = float4(0);
    for (int i = 0; i < 48; ++i) {
        float t = float(i) / 47.0;
        float4 w = float4(t, 1.0 - abs(2.0 * t - 1.0), 1.0 - t, 1.0);
        sum += float4(image.eval(c + d * (1.0 + s * (t - 0.5)))) * w;
        weight += w;
    }
    float4 result = sum / weight;
    return half4(half3(min(result.rgb, float3(result.a))), half(result.a));
}
